files.content:
:root {
  --bg: #1e1b2e;
  --card: #2a2640;
  --accent: #7c6cf0;
  --accent-strong: #9a8cff;
  --text: #f0eefc;
  --muted: #b8b2d8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(circle at top, #2d2748, var(--bg));
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 20px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.subtitle {
  color: var(--muted);
  font-size: 1rem;
  margin-bottom: 24px;
}

.stage {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

canvas {
  width: 100%;
  max-width: 320px;
  height: auto;
  aspect-ratio: 1 / 1;
}

.phase {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 20px;
  min-height: 1.9em;
  color: var(--accent-strong);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: 10px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
}

.btn:focus-visible {
  outline: 3px solid var(--accent-strong);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.primary {
  background: var(--accent);
  color: #fff;
}

.primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--muted);
}

.secondary:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--text);
}

.counter {
  color: var(--muted);
  font-size: 1rem;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .controls {
    flex-direction: column;
  }
  .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  var canvas = document.getElementById('breathCanvas');
  var ctx = canvas.getContext('2d');
  var phaseLabel = document.getElementById('phaseLabel');
  var cycleCountEl = document.getElementById('cycleCount');
  var startBtn = document.getElementById('startBtn');
  var stopBtn = document.getElementById('stopBtn');

  var INHALE_MS = 4000;
  var EXHALE_MS = 4000;
  var CYCLE_MS = INHALE_MS + EXHALE_MS;

  var running = false;
  var startTime = 0;
  var rafId = null;
  var cycles = 0;
  var lastPhase = '';

  var MIN_RADIUS = 30;
  var MAX_RADIUS = 140;

  function setPhase(text) {
    if (text !== lastPhase) {
      lastPhase = text;
      phaseLabel.textContent = text;
    }
  }

  function draw(radius) {
    var w = canvas.width;
    var h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Pixelated look: draw on a coarse grid.
    var pixel = 8;
    var cx = w / 2;
    var cy = h / 2;

    ctx.fillStyle = '#7c6cf0';
    var r2 = radius * radius;
    for (var y = 0; y < h; y += pixel) {
      for (var x = 0; x < w; x += pixel) {
        var dx = x + pixel / 2 - cx;
        var dy = y + pixel / 2 - cy;
        if (dx * dx + dy * dy <= r2) {
          ctx.fillRect(x, y, pixel, pixel);
        }
      }
    }
  }

  function frame(now) {
    if (!running) return;

    var elapsed = (now - startTime) % CYCLE_MS;
    if (elapsed < 0) elapsed += CYCLE_MS;

    var radius;
    if (elapsed < INHALE_MS) {
      var t = elapsed / INHALE_MS;
      radius = MIN_RADIUS + (MAX_RADIUS - MIN_RADIUS) * t;
      setPhase('Inhale');
    } else {
      var t2 = (elapsed - INHALE_MS) / EXHALE_MS;
      radius = MAX_RADIUS - (MAX_RADIUS - MIN_RADIUS) * t2;
      setPhase('Exhale');
    }

    draw(radius);

    var completed = Math.floor((now - startTime) / CYCLE_MS);
    if (completed > cycles) {
      cycles = completed;
      cycleCountEl.textContent = String(cycles);
    }

    rafId = requestAnimationFrame(frame);
  }

  function start() {
    if (running) return;
    running = true;
    startBtn.disabled = true;
    stopBtn.disabled = false;
    startTime = performance.now();
    lastPhase = '';
    rafId = requestAnimationFrame(frame);
    startBtn.blur();
  }

  function stop() {
    if (!running) return;
    running = false;
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    startBtn.disabled = false;
    stopBtn.disabled = true;
    setPhase('Ready');
    draw(MIN_RADIUS);
    stopBtn.blur();
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  draw(MIN_RADIUS);
})();
